local Singleton = import('Frame.Singleton')
local KTool = CS.Engine.Lib.KTool
local TimeZoneUtils = CS.Engine.Http.TimeZoneUtils
---@type ActivityUtils
local ActivityUtils = import("Game.Activity.ActivityUtils")
local ActivityConstants = import("Game.Activity.ActivityConstants")

---@class ActivityMgr
---@field GetInstance fun(self:ActivityMgr):ActivityMgr
local ActivityMgr = Class('ActivityMgr', Singleton)

function ActivityMgr:__init()
    ---@type ActivityComponent
    self._activityComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityComponent)
end

function ActivityMgr:__delete()
    self._activityComponent = nil
end

---初始化数据
function ActivityMgr:InitActivityHomeData(activityData)
    local comp = self:GetActivityComponent()
    comp:Initial(activityData)
    Events.Broadcast(Constants.EventNames.ActivityHomeIcomRefresh, {})
end

---更新本地活动数据
---@param isRefresh boolean 是否刷新活动页面
function ActivityMgr:UpdateActivityHomeData(isRefresh)
    isRefresh = isRefresh == true
    GameUtils.Request(Interfaces.ActivityHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local activityData = checkTable(response.data.activities)
        self:UpdateSpecialRed(activityData)
        ActivityUtils.ConventSecondToTimeStamp(activityData)
        self:InitActivityHomeData(activityData)

        if isRefresh then
            Events.Broadcast(Constants.EventNames.ActivityDialogRefresh, response.data)
        end

        -- 更新主界面活动入口按钮的红点数据
        local data = checkTable(response.data)
        for i, v in ipairs(checkTable(data.activities)) do
            if checkInt(v.redDotHint) >= 0 then
                ---@type RedPointMgrComponent
                local redPointCom = GameUtils.GetEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)
                redPointCom:UpdateRedPointData({unReceivedActivity = 0})
                break
            end
        end
    end)
end
function ActivityMgr:UpdateSpecialRed(activityData)
    for k, v in pairs(activityData) do
        if checkInt(v.redDotHint) == -1 then
            if checkInt(v.type)  == ActivityConstants.ActivityType.ActivityWeekendGift then
                local isRed = ActivityMgr:IsHasFirstOrEverydayEnterRedPoint(v.id ,false)
                v.redDotHint = checkInt(isRed)
            end
        end
    end
end

---通过活动类型获取活动Id
---同活动类型存在多个时返回第一个
---@param activityType ActivityConstants.ActivityType
function ActivityMgr:GetActivityIdByActivityType(activityType)
    local activityData = self:GetActivityData()
    for i, v in ipairs(activityData) do
        if checkInt(v.type) == checkInt(activityType)then
            return v.id
        end
    end
end

---设置activityComponent
---@return ActivityComponent
function ActivityMgr:GetActivityComponent()
    return self._activityComponent 
end

---获取活动homeData
function ActivityMgr:GetActivityData()
    return self:GetActivityComponent():GetActivityData()
end

---获取活动额外红点总状态
function ActivityMgr:GetTotalActivityExtraRedPointState()
    local activityData = self:GetActivityData()
    local state = -1
    for i, v in ipairs(activityData or {}) do
        if self:GetActivityExtraRedPointState(v.type, v.id) == 0 then
            state = 0
            break
        end
    end
    return state
end

---获取活动额外红点状态
---@param activityType ActivityConstants.ActivityType 活动类型
---@param activityUuid integer 活动id
function ActivityMgr:GetActivityExtraRedPointState(activityType, activityUuid)
    if checkInt(activityType) == ActivityConstants.ActivityType.BossChallenge or 
            checkInt(activityType) == ActivityConstants.ActivityType.FishingContest then
        -- 每日首次进入前红点提示
        local timestamp = self:GetActivityComponent():GetActivityEnterTime(activityUuid)
        return os.date('!%x', timestamp + 3600 * 3) == os.date('!%x', TimeZoneUtils.UtcSeconds + 3600 * 3) and -1 or 0
    else
        return -1
    end
end

function ActivityMgr:GetActivityWithTypeAndSkinId(activityType, skinId)
    local uuId = 0
    if checkInt(activityType) == ActivityConstants.ActivityType.QuestSkinExperience then
        local activityData = self:GetActivityData()
        for i, v in ipairs(activityData) do
            if checkInt(v.type) == checkInt(activityType) and checkNumber(v.skinId) == checkNumber(skinId) then
                uuId = checkNumber(v.id)
                break
            end
        end
    end
    return uuId
end

--- 页签是否有小红点
---@param activityId integer
---@return boolean
function ActivityMgr:HasActivityDojoRedDotHint(activityId)
    local hasRedDot = false
    local dojo = self:GetActivityComponent():GetDojoByActivityId(activityId)
    if isNotNull(dojo) and dojo.redDotHint == 0 then
        hasRedDot = true
    end
    return hasRedDot
end

function ActivityMgr:UpdateHomeGachaActivityData()
    GameUtils.Request(Interfaces.HomeGachaActivity, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        
        local responseData  = checkTable(response.data)
        local gachaponUtils = import('Game.Gachapon.GachaponUtils')
        local gachaponComp  = gachaponUtils.GetGachaponComp()
        gachaponComp:UpdateHomeActivityDatas(responseData.callActivity)
    end)
end

--overseaMall/buyActivityGoods (购买活动道具)

---购买活动道具
---@param  activityUuid number 活动唯一id
---@param  activityType number 活动类型
---@param  goodsId number 购买的道具id
---@param  num number 购买道具的次数
function ActivityMgr:RequestBuyActivityGoods(activityUuid, activityType, goodsId, num, cb)
    GameUtils.Request(Interfaces.BuyActivityGoods,{activityUuid = activityUuid, activityType = activityType, goodsId = goodsId, num = num}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local responseData = checkTable(response.data)
        local rewards = checkTable(responseData.rewards)
        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards, true)
        end
        if cb then
            cb()
        end
    end)
end


---活动道具价格
---@return number,number  消耗货币id，消耗货币数量
function ActivityMgr:GetGoodsPrice(goodsId)
    if self.GoodsPriceVoDic == nil then
        ---@type table<number,ActivityGoodsPriceVo>
        self.GoodsPriceVoDic = {}
        ---@type ActivityGoodsPriceVo[]
        local vos = CfUtils.GetCf(AutoIds.IdSetting6134, "ActivityGoodsPriceVo",true)
        for i, v in ipairs(vos) do
            self.GoodsPriceVoDic[v.getItemId] = v
        end
    end
    local vo = self.GoodsPriceVoDic[goodsId]
    if isNull(vo) then
        return
    end
    return vo.itemId,vo.itemNum
end
---@param activityId integer @ 活动id  
---@param isEveryDay boolean @ 是否是每次 ， 如果不是每日就直接是首次进入
function ActivityMgr:IsHasFirstOrEverydayEnterRedPoint(activityId , isEveryDay)
    if isEveryDay then
        ---@type PlayerComponent
        local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local currentDayId = os.date("%Y%m%d", PlayerComponent:GetPlayerDojo():GetServerTime())
        local isRed = CfUtils.GetLocalData(string.format("ActvityType_%s_%s" , activityId , currentDayId) , "0")   
        return  isRed
    else
        local isRed = CfUtils.GetLocalData(string.format("ActvityType_%s" , activityId ) , "0")   
        return  isRed
    end
end

---@param activityId integer @ 活动id  
---@param isEveryDay boolean @ 更新首次和每日的红点
function ActivityMgr:UpdateFirstOrEverydayEnterRedPoint(activityId , isEveryDay)
    if isEveryDay then
        ---@type PlayerComponent
        local PlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local currentDayId = os.date("%Y%m%d", PlayerComponent:GetPlayerDojo():GetServerTime())
        CfUtils.WriteLocalData(string.format("ActvityType_%s_%s" , activityId , currentDayId) , "-1")   
    else
        CfUtils.WriteLocalData(string.format("ActvityType_%s" , activityId ) , "-1")   
    end
end

function ActivityMgr.GetActivityRule(ruleId)
    local ruleRow = CfUtils.GetCfLine(AutoIds.IdSetting12, ruleId)
    local text
    if isNotNull(ruleRow) then
        text = parse_localizeText(ruleRow, "descr", true, "")
    end
    return text
end

---获取限时连续礼包数据
function ActivityMgr:GetPayTimeChestData()
    return self:GetActivityComponent():GetPayTimeChestData()
end

return ActivityMgr